	-- Step 44: Clubtoe
	-- {area:16723} Sunnyglade · {npc:260931} Clubtoe · {npc:256710} Tran'gul
	["West to {area:16723} again: {npc:260931}, a Twilight miner who wants out, waits at the town's eastern edge. Talk him round, then hand {npc:256710}'s quest in; one of the missing ogres stands a few steps west."] = "Retournez à l'ouest jusqu'à {area:16723} : {npc:260931}, un mineur du Crépuscule qui veut s'en sortir, attend à la lisière est du village. Convainquez-le, puis rendez la quête de {npc:256710} ; l'un des ogres disparus se tient à quelques pas à l'ouest.",
	-- {npc:260931} Clubtoe
	["talk {npc:260931} round"] = "convainquez {npc:260931}",
	-- {npc:261208} Twilight Brute
	["{npc:261208}, a few steps west"] = "{npc:261208}, à quelques pas à l'ouest",

	-- Step 45: The ritual grounds
	["The ritual grounds"] = "Les terrains rituels",
	-- {area:16723} Sunnyglade · {npc:256899} Chogg'Zac
	["The ritualists and their empowered brutes gather at the ritual circles in the middle of {area:16723}: wreck five of the circles.\nCareful: {npc:256899}, the elite ogre (level 41), walks through here from the western streets: watch for him before each pull."] = "Les ritualistes et leurs brutes renforcées se rassemblent autour des cercles rituels au milieu de {area:16723} : détruisez cinq de ces cercles.\nAttention : {npc:256899}, l'ogre élite (niveau 41), passe par ici depuis les rues ouest : surveillez-le avant chaque attaque.",
	-- plural, as words: Twilight Ritual Circles = {npc:262006} Twilight Ritual Circle
	["destroy 5 Twilight Ritual Circles"] = "détruire 5 Cercles rituels du Crépuscule",

	-- Step 47: Chogg'Zac
	-- {npc:256899} Chogg'Zac · {area:16723} Sunnyglade · {npc:255829} Clugfist · {area:16726} Bolder'ok · {quest:95420} Land of Giants · {npc:258570} Da'grosh
	["Careful: {npc:256899}, the two-headed ogre at the western edge of {area:16723}, is an elite (level 41): grouping up is advised under 43. Clear the cultists around him first and come in with full health and mana: recorded players of 42-43 killed him alone. {npc:255829}'s quests in {area:16726} wait on this one: skip him and {quest:95420}, the {area:16726} quests and {npc:258570}'s camp in the west go with him (about 21,000 XP); the guide then leaves them out."] = "Attention : {npc:256899}, l'ogre à deux têtes à la lisière ouest de {area:16723}, est un élite (niveau 41) : un groupe est conseillé sous le niveau 43. Éliminez d'abord les cultistes autour de lui et engagez avec toute votre vie et votre mana : des joueurs de niveau 42-43 l'ont tué seuls. Les quêtes de {npc:255829} à {area:16726} en dépendent : si vous le passez, {quest:95420}, les quêtes de {area:16726} et le camp de {npc:258570} à l'ouest sautent aussi (environ 21 000 PX) ; le guide les omet alors.",

	-- Step 48: Clubtoe
	-- {quest:95418} Spread the Word · {npc:256710} Tran'gul · {area:16743} Rog'mar
	["{quest:95418}: for {npc:256710} in {area:16743}"] = "{quest:95418} : pour {npc:256710} à {area:16743}",

	-- Step 49: Tran'gul
	-- {area:16743} Rog'mar · {npc:260931} Clubtoe · {npc:256710} Tran'gul · {npc:255829} Clugfist
	["East back to {area:16743}: {npc:260931}'s word goes to {npc:256710}, and {npc:256710}'s to {npc:255829}, the ogres' chieftain."] = "Retournez à l'est jusqu'à {area:16743} : le message de {npc:260931} va à {npc:256710}, et celui de {npc:256710} à {npc:255829}, le chef des ogres.",
	-- {quest:95420} Land of Giants · {npc:255829} Clugfist · {area:16726} Bolder'ok
	["{quest:95420}: for {npc:255829} in {area:16726}"] = "{quest:95420} : pour {npc:255829} à {area:16726}",

	-- Step 50: WANTED: Scoutmaster Vargas
	-- {npc:260211} Scoutmaster Vargas · {npc:256728} Na'zok · {npc:258031} Neza Bloodsnout
	["{npc:260211} is an elite (level 42) at the Alliance scouts' camp in the hills south-east of {npc:256728}, where you go next: grouping up is advised. The poster hangs in the middle of the fort; {npc:258031} takes the eye, later in this guide."] = "{npc:260211} est un élite (niveau 42) au camp des éclaireurs de l'Alliance, dans les collines au sud-est de {npc:256728}, votre prochaine destination : un groupe est conseillé. L'affiche est accrochée au milieu du fort ; {npc:258031} récupère l'œil, plus loin dans ce guide.",
	-- {object:707249} Wanted (no name in this language: may be words)
	["the {object:707249} poster"] = "l'affiche {object:707249}",

	-- Step 51: Na'zok's camp
	-- {npc:256728} Na'zok
	["{npc:256728}'s camp"] = "Camp de {npc:256728}",
	-- {area:16743} Rog'mar · {npc:256728} Na'zok
	["North-east from {area:16743} up into the hills: {npc:256728} watches the Paletusk boars from his camp."] = "Au nord-est de {area:16743}, montez dans les collines : {npc:256728} surveille les sangliers brochepâles depuis son camp.",

	-- Step 52: Bolder'ok
	-- {area:16726} Bolder'ok · {npc:255829} Clugfist
	["North-west to {area:16726}, the ogres' town. {npc:255829}, its chieftain, sits on the hill. The ogres are friendly while you leave them alone."] = "Au nord-ouest jusqu'à {area:16726}, la ville des ogres. {npc:255829}, leur chef, est assis sur la colline. Les ogres restent amicaux tant que vous les laissez tranquilles.",

	-- Step 53: The Twilight ogres' camp
	["The Twilight ogres' camp"] = "Le camp des ogres du Crépuscule",
	-- {npc:256728} Na'zok · {npc:260973} Klunk · {item:269257} Skullbasher · {npc:260211} Scoutmaster Vargas
	-- plural, as words: Twilight Maulers = {npc:260968} Twilight Mauler · Farholde Ambushers = {npc:260023} Farholde Ambusher
	["The Twilight Maulers and Firecallers camp on the ridge east of {npc:256728}. {npc:260973}, who carries the {item:269257}, stands among them. Just south of the ogres, {npc:260211} (an Alliance elite, level 42) and his Farholde Ambushers hold the scouts' camp: keep north of it unless you came with a group for him."] = "Les Marteleurs du Crépuscule et les Invocateurs de feu campent sur la crête à l'est de {npc:256728}. {npc:260973}, qui porte {item:269257}, se tient parmi eux. Juste au sud des ogres, {npc:260211} (élite de l'Alliance, niveau 42) et ses Embusqués de Farholde tiennent le camp des éclaireurs : restez au nord à moins d'être venu en groupe pour lui.",
	-- {item:269257} Skullbasher · {npc:260973} Klunk
	["{item:269257}, from {npc:260973}"] = "{item:269257}, sur {npc:260973}",

	-- Step 55: The paletusks
	["The paletusks"] = "Les brochepâles",
	-- {npc:256728} Na'zok
	-- plural, as words: Young Paletusks = {npc:258331} Young Paletusk · Mature Paletusks = {npc:255851} Mature Paletusk
	["South down the hills, round the west side of the Alliance scouts' camp: tap the Young Paletusks with {npc:256728}'s staff to send them home; the Mature Paletusks around the hills drop the boar meat."] = "Descendez les collines vers le sud en contournant par l'ouest le camp des éclaireurs de l'Alliance : touchez les Jeunes brochepâles avec le bâton de {npc:256728} pour les renvoyer chez eux ; les Brochepâles adultes autour des collines donnent la viande de sanglier.",
	-- {item:268521} Swineherd's Staff
	-- plural, as words: Young Paletusks = {npc:258331} Young Paletusk
	["{item:268521}, on the Young Paletusks"] = "{item:268521}, sur les Jeunes brochepâles",
	-- {item:769} Chunk of Boar Meat
	-- plural, as words: Mature Paletusks = {npc:255851} Mature Paletusk
	["{item:769}, from the Mature Paletusks"] = "{item:769}, sur les Brochepâles adultes",

	-- Step 57: Jom-jom's Escape
	-- {npc:258048} Jom-jom · {npc:256728} Na'zok · {area:16726} Bolder'ok
	["{npc:258048} waits by the Twilight ogres' camp north-east of {npc:256728}: take him home to {area:16726} and keep the cultists off him. If he falls, take the quest from him again."] = "{npc:258048} attend près du camp des ogres du Crépuscule, au nord-est de {npc:256728} : ramenez-le chez lui à {area:16726} en le protégeant des cultistes. S'il meurt, reprenez la quête auprès de lui.",
	-- {npc:258048} Jom-jom · {area:16726} Bolder'ok
	["help {npc:258048} reach {area:16726}"] = "aidez {npc:258048} à rejoindre {area:16726}",

	-- Step 58: Bolder'ok
	-- {npc:255829} Clugfist · {npc:257062} Jezap Jinglesprocket · {quest:94668} Bloodmaster's Ring
	["Back to {npc:255829} on his hill. {npc:257062} runs the {quest:94668} just below it."] = "Retournez voir {npc:255829} sur sa colline. {npc:257062} gère {quest:94668} juste en contrebas.",

	-- Step 59: Clugfist
	-- {quest:95428} Clugfist's Decree · {npc:256418} Krom'rosh · {area:16743} Rog'mar
	["{quest:95428}: for {npc:256418} in {area:16743}, later in this guide"] = "{quest:95428} : pour {npc:256418} à {area:16743}, plus loin dans ce guide",
	-- {quest:94669} Pay to Play
	["{quest:94669}: the Ring's bouts, one-on-one fights with elites (41-45); a deposit first"] = "{quest:94669} : les combats de l'Arène, en duel contre des élites (41-45) ; un dépôt d'abord",

	-- Step 60: The Bloodmaster's Ring: Buzzbeak
	-- {quest:94670} Bloodmaster's Ring
	["The {quest:94670}: Buzzbeak"] = "{quest:94670} : Buzzbeak",
	-- {npc:255829} Clugfist · {npc:258626} Mog'thar · {npc:257059} Chub'chob · {npc:257062} Jezap Jinglesprocket
	["Each bout is a fight in the ring below {npc:255829}'s hill against an elite: Buzzbeak (41), Kronk and Bonegnaw (42), {npc:258626} (43), Snufflesnout (44) and {npc:257059} (45). Come in rested, with full health and mana; if a bout goes wrong, {npc:257062} offers it again."] = "Chaque combat a lieu dans l'arène sous la colline de {npc:255829}, contre un élite : Buzzbeak (41), Kronk et Bonegnaw (42), {npc:258626} (43), Snufflesnout (44) et {npc:257059} (45). Arrivez reposé, vie et mana au maximum ; si un combat tourne mal, {npc:257062} vous le propose à nouveau.",
	-- {quest:94670} Bloodmaster's Ring
	["{quest:94670}: Buzzbeak"] = "{quest:94670} : Buzzbeak",
	["beat Buzzbeak"] = "battez Buzzbeak",

	-- Step 61: The Bloodmaster's Ring: Kronk and Bonegnaw
	-- {quest:94670} Bloodmaster's Ring
	["The {quest:94670}: Kronk and Bonegnaw"] = "{quest:94670} : Kronk et Bonegnaw",
	["Kronk"] = "Kronk",
	["Bonegnaw"] = "Bonegnaw",

	-- Step 62: The Bloodmaster's Ring: Mog'thar
	-- {quest:94962} Bloodmaster's Ring · {npc:258626} Mog'thar
	["The {quest:94962}: {npc:258626}"] = "{quest:94962} : {npc:258626}",

	-- Step 63: The Bloodmaster's Ring: Snufflesnout and Chub'chob
	-- {quest:94964} Bloodmaster's Ring · {npc:257059} Chub'chob
	["The {quest:94964}: Snufflesnout and {npc:257059}"] = "Le {quest:94964} : Renifle-groin et {npc:257059}",
	-- {npc:257062} Jezap Jinglesprocket · {npc:258626} Mog'thar
	["{npc:257062} offers the last two once Gobam's errands are done (players' recordings), which this guide leaves out. They are level 44 and 45: leave them for later if {npc:258626} was a close fight."] = "{npc:257062} propose les deux derniers une fois les courses de Gobam terminées (d'après des enregistrements de joueurs), que ce guide laisse de côté. Ils sont de niveau 44 et 45 : gardez-les pour plus tard si le combat contre {npc:258626} a été serré.",
	["Snufflesnout (44)"] = "Renifle-groin (44)",
	-- {npc:255829} Clugfist
	["{npc:255829}, on the hill"] = "{npc:255829}, sur la colline",

	-- Step 64: Powderfuse Port
	-- {area:16727} Powderfuse Port · {npc:255897} Friz Frazzlespark · {npc:259962} Fimbo Greasemitz · {npc:259961} Wharfmaster Whizzbuzz
	["South-east down out of the hills to {area:16727}, the goblins' harbour on the coast. {npc:255897} keeps a stall at the west end of the docks, {npc:259962} cooks by the inn, and {npc:259961} works the north pier."] = "Descendez des collines vers le sud-est jusqu'à {area:16727}, le port gobelin sur la côte. {npc:255897} tient un étal à l'extrémité ouest des quais, {npc:259962} cuisine près de l'auberge, et {npc:259961} travaille sur la jetée nord.",
	-- {object:628948} WANTED! (no name in this language: may be words) · {npc:260235} Trapclaw
	["The {object:628948} poster by the inn: {npc:260235}"] = "L'affiche {object:628948} près de l'auberge : {npc:260235}",

	-- Step 65: Wharfmaster Whizzbuzz
	-- {npc:259961} Wharfmaster Whizzbuzz · {item:277974} Twice Reordered Package
	["{npc:259961} on the north pier takes Lozgil's {item:277974}."] = "{npc:259961}, sur la jetée nord, prend le {item:277974} de Lozgil.",

	-- Step 66: WANTED: Old Rot-Chum
	-- {npc:257001} Old Rot-Chum
	["{npc:257001} is an elite (level 42) on the south shore: grouping up is advised."] = "{npc:257001} est un élite (niveau 42) sur la rive sud : il est conseillé de former un groupe.",
	-- {object:628948} WANTED! (no name in this language: may be words)
	["The {object:628948} poster by the inn"] = "L'affiche {object:628948} près de l'auberge",

	-- Step 67: The murlocs, south-west
	["The murlocs, south-west"] = "Les murlocs, au sud-ouest",
	-- {quest:95260} Terrors From the Deep · {npc:260231} Argo Brinewhistle
	["South-west along the shore from the port: the saltwater murlocs camp on the beaches. On the way, a painted hide is stretched beside the path: it starts {quest:95260} for {npc:260231} at the docks."] = "Au sud-ouest le long du rivage depuis le port : les murlocs d'eau salée campent sur les plages. En chemin, une peau peinte est tendue à côté du sentier : elle lance {quest:95260} pour {npc:260231} sur les quais.",

	-- Step 69: Back through the port
	["Back through the port"] = "Retour par le port",
	["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "Revenez vers le nord le long du rivage : rendez les murlocs et la peau sur les quais en allant vers les rampants.",
	-- {quest:95261} It Takes Guts
	["{quest:95261}: the beasts' entrails come as you go; the mushrooms grow on the ridge west of the pirates"] = "{quest:95261} : les entrailles des bêtes viennent en chemin ; les champignons poussent sur la crête à l'ouest des pirates",

	-- Step 70: Beast Entrails as you go
	-- {item:268632} Beast Entrails
	["{item:268632} as you go"] = "{item:268632} en chemin",
	-- {zone:2548} Riverglades · {item:268632} Beast Entrails · {npc:260231} Argo Brinewhistle · {npc:257001} Old Rot-Chum · {npc:263380} Ghostmaw
	["Most beasts in the {zone:2548} drop {item:268632} for {npc:260231}: the shore crawlers on this coast and the boars on the ridge west of the pirates.\nCareful: {npc:257001} (elite, 42) wanders the shore and {npc:263380} (elite, 42) the river: take your beasts away from them."] = "La plupart des bêtes de {zone:2548} lâchent des {item:268632} pour {npc:260231} : les rampants du rivage sur cette côte et les sangliers sur la crête à l'ouest des pirates.\nAttention : {npc:257001} (élite, 42) erre sur le rivage et {npc:263380} (élite, 42) dans la rivière : éloignez vos bêtes d'eux.",

	-- Step 71: The crawlers and Trapclaw
	-- {npc:260235} Trapclaw
	["The crawlers and {npc:260235}"] = "Les rampants et {npc:260235}",
	-- {npc:259962} Fimbo Greasemitz · {npc:260231} Argo Brinewhistle · {npc:260235} Trapclaw · {npc:259758} Gul'gash
	["North along the beach from the docks: the crawlers drop the meat for {npc:259962}, and their entrails count for {npc:260231}. {npc:260235}, a big crab, scuttles along the rocks east of the docks. {npc:259758}, a rare elite of level 49, roams this coast from the docks up to the pirates' camp: if you see him, keep well away."] = "Remontez la plage vers le nord depuis les quais : les rampants lâchent la viande pour {npc:259962}, et leurs entrailles comptent pour {npc:260231}. {npc:260235}, un gros crabe, se déplace sur les rochers à l'est des quais. {npc:259758}, un rare élite de niveau 49, parcourt cette côte des quais jusqu'au camp des pirates : si vous le voyez, restez bien à l'écart.",

	-- Step 72: The Eastsea pirates
	["The Eastsea pirates"] = "Les pirates de la mer de l'Est",
	-- {npc:259758} Gul'gash
	["North-east along the coast to the pirates' camp on the cliffs. The buccaneers and musketeers carry the smuggled goods. {npc:259758} walks the camp too: keep an eye out for him."] = "Au nord-est le long de la côte jusqu'au camp des pirates sur les falaises. Les boucaniers et les mousquetaires portent les marchandises de contrebande. {npc:259758} parcourt aussi le camp : surveillez-le.",

	-- Step 73: Powderfuse Port
	["Back to the port, from the north pier west through the docks."] = "Retournez au port, depuis la jetée nord vers l'ouest à travers les quais.",
	-- {quest:95293} Smuggler's Special · {npc:260390} Captain Bentcoin
	["{quest:95293}: for {npc:260390} at the pirates' camp"] = "{quest:95293} : pour {npc:260390} au camp des pirates",

	-- Step 75: The pirates' second wave
	["The pirates' second wave"] = "La deuxième vague des pirates",
	-- {npc:259758} Gul'gash
	-- plural, as words: Eastsea Raiders = {npc:257915} Eastsea Raider
	["North along the coast from the port: the Eastsea raiders and bombardiers have dug in on the slopes west of the buccaneers' camp, among their powder kegs. Watch for {npc:259758} on these cliffs.\nCareful: the Eastsea Raiders are level 44-45, a level or two over you here: pull them one at a time from the edge of the slopes and keep clear of the camp behind them."] = "Longez la côte vers le nord depuis le port : les écumeurs et bombardiers des mers de l'Est se sont retranchés sur les pentes à l'ouest du camp des boucaniers, parmi leurs barils de poudre. Méfiez-vous de {npc:259758} sur ces falaises.\nAttention : les Ecumeurs des mers de l'Est sont de niveau 44-45, un ou deux niveaux au-dessus de vous ici : attirez-les un par un depuis le bord des pentes et tenez-vous à l'écart du camp derrière eux.",

	-- Step 76: Captain Bentcoin
	-- {npc:260390} Captain Bentcoin · {npc:260391} Captain Haynes
	["East along the cliffs to the far end of the pirates' camp: {npc:260390} waits by the water, {npc:260391} beside him."] = "Vers l'est le long des falaises jusqu'au bout du camp des pirates : {npc:260390} attend au bord de l'eau, {npc:260391} à côté de lui.",

	-- Step 77: Powderfuse Port
	["Back to the port."] = "Retournez au port.",
	-- {npc:255897} Friz Frazzlespark · {quest:95296} Shipping and Handling · {npc:260405} Wharfmaster Steamfizzle · {area:977} Steamwheedle Port · {zone:1444} Feralas · {zone:1446} Tanaris
	["{npc:255897}: {quest:95296}, for {npc:260405} at {area:977} in the {zone:1444} & {zone:1446} guide"] = "{npc:255897} : {quest:95296}, pour {npc:260405} à {area:977}, dans le guide {zone:1444} & {zone:1446}",

	-- Step 78: The pirates' ships
	["The pirates' ships"] = "Les navires des pirates",
	-- {quest:95124} Admiral Lamora · {npc:259758} Gul'gash
	["Out to the pirates' cliffs once more. Plant Whizzbuzz's charges on the three ships moored below the camp, south to north; {quest:95124} stands by the middle one, with her loot chest beside her. Keep an eye out for {npc:259758} on the way.\nCareful: {quest:95124} is level 45, a level or two over you here: clear the deck around her first and come in with full health."] = "Retournez encore une fois aux falaises des pirates. Posez les charges de Whizzbuzz sur les trois navires amarrés sous le camp, du sud au nord ; {quest:95124} se tient près de celui du milieu, avec son coffre à butin à côté d'elle. Méfiez-vous de {npc:259758} en chemin.\nAttention : {quest:95124} est de niveau 45, un ou deux niveaux au-dessus de vous ici : nettoyez le pont autour d'elle d'abord et arrivez avec toute votre vie.",
	-- {item:268505} Remote Explosive Charge
	["{item:268505}, the southern ship"] = "{item:268505}, le navire sud",
	["the middle ship"] = "le navire du milieu",
	["the northern ship"] = "le navire nord",

	-- Step 79: Rotflesh Mushrooms
	-- plural, as words: Rotflesh Mushrooms = {item:268664} Rotflesh Mushroom
	["Rotflesh Mushrooms"] = "Champignons cadavériques",
	-- plural, as words: Rotflesh Mushrooms = {item:268664} Rotflesh Mushroom · Mature Paletusks = {npc:255851} Mature Paletusk
	["West from the northern ship, up the ridge: the Rotflesh Mushrooms grow among the rocks, close to the Twilight ogres' camp. The Mature Paletusks on the ridge give entrails too."] = "À l'ouest du navire nord, montez sur la crête : les Champignons cadavériques poussent parmi les rochers, près du camp des ogres du Crépuscule. Les Brochepâles adultes de la crête donnent aussi des entrailles.",

	-- Step 80: Finish the Beast Entrails
	-- {item:268632} Beast Entrails
	["Finish the {item:268632}"] = "Terminez les {item:268632}",
	-- {npc:259758} Gul'gash
	["South-east back towards the port: the shore crawlers on the beach north of the docks are the quickest entrails. {npc:259758} wanders down to this beach too."] = "Retournez vers le port au sud-est : les rampants du rivage sur la plage au nord des quais sont le moyen le plus rapide d'obtenir les entrailles. {npc:259758} descend aussi jusqu'à cette plage.",

	-- Step 81: Powderfuse Port
	["Down to the port."] = "Descendez au port.",
	-- {quest:95267} The Monster Surfaces · {npc:257001} Old Rot-Chum
	["{quest:95267}: a big beast in the shallows south-west of the port, near {npc:257001}, the elite"] = "{quest:95267} : une grosse bête dans les hauts-fonds au sud-ouest du port, près de {npc:257001}, l'élite",

	-- Step 82: The Monster Surfaces
	-- {npc:260244} Monstrous Threshadon · {npc:257001} Old Rot-Chum
	["The {npc:260244} prowls the shallows south-west of the port, below the murlocs' beaches. {npc:257001}, an elite, walks the shore close by: give him room."] = "Le {npc:260244} rôde dans les hauts-fonds au sud-ouest du port, sous les plages des murlocs. {npc:257001}, un élite, arpente le rivage tout près : gardez vos distances.",

	-- Step 84: Rog'mar
	-- {area:16743} Rog'mar · {npc:256418} Krom'rosh · {npc:255829} Clugfist · {npc:258570} Da'grosh
	["Back to {area:16743} from the port, where your Hearthstone is set. {npc:256418} in the middle of the fort: {npc:255829}'s word sends him looking for {npc:258570}, his warrior in the west."] = "Retournez du port à {area:16743}, où votre Pierre de foyer est liée. {npc:256418}, au milieu du fort : le message de {npc:255829} l'incite à chercher {npc:258570}, son guerrier parti à l'ouest.",
	-- {quest:94744} The Wayward Warrior · {npc:258570} Da'grosh · {area:16723} Sunnyglade
	["{quest:94744}: for {npc:258570}, west of {area:16723}"] = "{quest:94744} : pour {npc:258570}, à l'ouest de {area:16723}",

	-- Step 86: Da'grosh
	-- {area:16743} Rog'mar · {area:16723} Sunnyglade · {area:16685} Twilight's Shroud · {npc:258570} Da'grosh · {npc:256418} Krom'rosh
	["West from {area:16743} through {area:16723} and on up the valley towards {area:16685}: {npc:258570}, {npc:256418}'s wayward warrior, keeps a camp in the hills below the Twilight cult's fortress."] = "Allez vers l'ouest depuis {area:16743}, traversez {area:16723} et remontez la vallée vers {area:16685} : {npc:258570}, le guerrier égaré de {npc:256418}, a un camp dans les collines sous la forteresse du culte du Crépuscule.",

	-- Step 87: Crag'rog
	-- {npc:260993} Crag'rog · {area:16726} Bolder'ok · {npc:258570} Da'grosh
	["{npc:260993}, a {area:16726} ogre, hides in the cave west of {npc:258570}'s camp."] = "{npc:260993}, un ogre de {area:16726}, se cache dans la grotte à l'ouest du camp de {npc:258570}.",

	-- Step 88: The Twilight camps
	["The Twilight camps"] = "Les camps du Crépuscule",
	-- {npc:258570} Da'grosh · {npc:256881} Overlord Kilgar · {npc:256891} Executioner Morg · {npc:258023} Sergeant Riftan
	-- plural, as words: Rog'mar Scouts = {npc:257450} Rog'mar Scout · Twilight Enforcers = {npc:256800} Twilight Enforcer · Farholde Lookouts = {npc:258686} Farholde Lookout
	["The cult's camps fill the valley south and west of {npc:258570}. Free the captive Rog'mar Scouts as you find them. Twilight Enforcers (elites, level 45) patrol through the camps: watch where they walk before each pull. {npc:256881} and {npc:256891} (elites, 46) hold the fortress at the valley's head: pull the cultists away from them. {npc:258023}'s Alliance camp sits at the valley's south end, and its Farholde Lookouts (level 46) attack the Horde: stay north of it."] = "Les camps du culte remplissent la vallée au sud et à l'ouest de {npc:258570}. Libérez les Éclaireurs Rog'mar captifs au fur et à mesure. Des Massacreurs du Crépuscule (élites, niveau 45) patrouillent entre les camps : observez leur trajet avant chaque attaque. {npc:256881} et {npc:256891} (élites, 46) tiennent la forteresse au fond de la vallée : attirez les cultistes loin d'eux. Le camp de l'Alliance de {npc:258023} se trouve à l'extrémité sud de la vallée, et ses Guetteurs de Farholde (niveau 46) attaquent la Horde : restez au nord.",
	-- plural, as words: Rog'mar Scouts = {npc:257450} Rog'mar Scout
	["free five captive Rog'mar Scouts"] = "libérer cinq Éclaireurs Rog'mar captifs",

	-- Step 89: The ogre mine
	["The ogre mine"] = "La mine des ogres",
	-- plural, as words: Twilight Enforcers = {npc:256800} Twilight Enforcer
	["North of the camps the cult works ogre miners in a mine: talk five of them into rising up against their masters.\nCareful: Twilight Enforcers (elites, level 45) walk past the mine's mouth on their way through the camps. Wait for one to pass before you go in."] = "Au nord des camps, le culte fait travailler des mineurs ogres dans une mine : convainquez-en cinq de se soulever contre leurs maîtres.\nAttention : des Massacreurs du Crépuscule (élites, niveau 45) passent devant l'entrée de la mine en traversant les camps. Attendez qu'un d'eux soit passé avant d'entrer.",
	-- plural, as words: Ogre Miners = {npc:260995} Ogre Miner
	["recruit five Ogre Miners"] = "recruter cinq Mineurs ogres",

	-- Step 92: Bring Me His Head
	-- {npc:256881} Overlord Kilgar
	["{npc:256881} is an elite (level 46) in the fortress at the head of the valley, with the Enforcers around him: grouping up is advised."] = "{npc:256881} est un élite (niveau 46) dans la forteresse au fond de la vallée, entouré des Massacreurs : un groupe est conseillé.",

	-- Step 93: Twilight's Shroud
	-- {area:340} Kargath · {area:3} Badlands · {npc:258570} Da'grosh · {area:16685} Twilight's Shroud
	["The next guide flies from {area:340} in the {area:3}: north out of {npc:258570}'s valley and up through {area:16685}, the way through to the {area:3}."] = "Le guide suivant part en vol de {area:340}, dans les {area:3} : sortez par le nord de la vallée de {npc:258570} et montez par {area:16685}, le passage vers les {area:3}.",

	-- Step 94: Kargath
	-- {area:3} Badlands · {area:340} Kargath
	["Across the {area:3} to {area:340}, the Horde fortress built into the cliffs at the zone's western edge: its flight master stands at the foot of the fortress."] = "Traversez les {area:3} jusqu'à {area:340}, la forteresse de la Horde bâtie dans les falaises à l'ouest de la zone : son Maître de vol se tient au pied de la forteresse.",
}
